package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;
public final class CreditCardsOverlay{private CreditCardsOverlay(){}public static void install(Activity a){if(!(a instanceof HomeActivity))return;View root=a.findViewById(android.R.id.content);if(root!=null)root.post(()->inject(a,root));}private static void inject(Activity a,View root){if(root.findViewWithTag("credit_cards_nav")!=null)return;ViewGroup content=(ViewGroup)root;if(content.getChildCount()==0)return;View v=content.getChildAt(0);if(!(v instanceof LinearLayout))return;LinearLayout outer=(LinearLayout)v;if(outer.getChildCount()==0)return;View last=outer.getChildAt(outer.getChildCount()-1);if(!(last instanceof LinearLayout))return;LinearLayout nav=(LinearLayout)last;Button b=new Button(a);b.setTag("credit_cards_nav");b.setText("▤\nTarjetas");b.setTextSize(11);b.setAllCaps(false);b.setOnClickListener(x->a.startActivity(new Intent(a,CreditCardsActivity.class)));nav.addView(b,new LinearLayout.LayoutParams(0,(int)(66*a.getResources().getDisplayMetrics().density),1));}}